import net.spell_engine.api.spell.*;import net.spell_engine.api.spell.registry.SpellRegistry;import net.spell_engine.internals.*;import net.spell_engine.internals.casting.*;import net.spell_engine.internals.container.*;import net.spell_engine.internals.target.*;import net.spell_engine.entity.SpellProjectile;import net.spell_power.api.*;import net.paladins.entity.BarrierEntity;
@Mod("phase_two_probe") public class PhaseTwoProbe {
 ServerLevel w;ServerPlayer p;int checks;final List<String> lines=new ArrayList<>();
 final List<net.minecraft.world.entity.projectile.arrow.AbstractArrow> seen=new ArrayList<>(); public PhaseTwoProbe(){NeoForge.EVENT_BUS.addListener(this::start);NeoForge.EVENT_BUS.addListener(this::joined);} void joined(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(event.getEntity() instanceof net.minecraft.world.entity.projectile.arrow.AbstractArrow a&&a.getOwner()==p){a.setDeltaMovement(new Vec3(.01,0,1).normalize().scale(3.15));seen.add(a);}}
 void eq(String name,double got,double expected){if(!Double.isFinite(got)||Math.abs(got-expected)>.015)throw new AssertionError(name+": "+got+" expected "+expected);checks++;lines.add(name+": "+got);}
 void yes(String name,boolean value){eq(name,value?1:0,1);}
 Holder<Spell> h(String id){return SpellRegistry.from(w).get(Identifier.parse(id)).orElseThrow();}
 Holder<MobEffect> fx(String id){return BuiltInRegistries.MOB_EFFECT.get(Identifier.parse(id)).orElseThrow();}
 void equip(String...mods){var o=(SpellContainerSource.Owner)p;var prev=o.getSpellContainers();o.setSpellContainers(new SpellContainerSource.Result(prev.activeContainer(),List.of(h("wizards:arcane_explosion")),List.of(),Arrays.stream(mods).map(this::h).toList(),List.of(new SpellContainerSource.SourcedContainer("probe",ItemStack.EMPTY,new net.spell_engine.api.spell.container.SpellContainer(net.spell_engine.api.spell.container.SpellContainer.ContentType.ANY,"","",0,List.of("wizards:arcane_explosion"))))));o.spellModifierCache().clear();}
 LivingEntity mob(double x,double y,double z){var m=EntityTypes.CREEPER.create(w,EntitySpawnReason.COMMAND);m.setNoAi(true);m.setNoGravity(true);m.setPos(x,y,z);m.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);m.setHealth(1000);w.addFreshEntity(m);return m;}
 SpellExecution.ImpactContext context(Holder<Spell> s){return new SpellExecution.ImpactContext().channeled(1).power(new SpellPower.Result(s.value().school,40,0,1));}
 SpellProjectile projectile(String id){var s=h(id);var def=s.value().deliver.projectile.projectile;var a=new SpellProjectile(w,p,p.getX(),p.getEyeY(),p.getZ(),SpellProjectile.Behaviour.FLY,s,context(s),def.perks.copy());a.range=s.value().range;a.setDeltaMovement(0,0,.9);w.addFreshEntity(a);return a;}
 void start(ServerStartedEvent event){w=event.getServer().overworld();try{
  p=net.neoforged.neoforge.common.util.FakePlayerFactory.get(w,new com.mojang.authlib.GameProfile(UUID.fromString("5ee19679-03cc-48f5-bb83-dc90e8af9d73"),"PhaseTwo"));p.setPos(0,80,0);w.addNewPlayer(p);p.getAbilities().instabuild=true;w.setChunkForced(0,0,true);equip();
  for(var old:w.getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(100)))if(old!=p)old.discard();for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)w.getChunk(x,z);reach();vanish();slash();boundary();barrage();
 }catch(Throwable e){finish(e);}}
 void finish(Throwable e){try{Files.writeString(Path.of("phase-two-result.txt"),e==null?"PASS "+checks+" checks\n":"FAIL "+e+"\n");Files.write(Path.of("phase-two-checks.txt"),lines);}catch(Exception ignored){}if(e!=null)e.printStackTrace();w.getServer().halt(false);}
 void reach(){
  p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));var a=p.getAttribute(Attributes.SCALE);var id=Identifier.parse("test:growth");double original=a.getBaseValue();
  for(double size:new double[]{.5,.75,1,1.36,1.5,2.5,4}){a.setBaseValue(size);double expected=net.bettercombat.logic.PlayerAttackHelper.getRangeForItem(p,p.getMainHandItem())*net.bettercombat.BetterCombatMod.config.getAttackRangeMultiplierForScale(p.getScale());eq("Native and BetterCombat range agree scale="+size,p.entityInteractionRange(),expected);var near=mob(0,80,.7);yes("Close target remains reachable size="+size,p.isWithinEntityInteractionRange(near,0));near.discard();}
  a.setBaseValue(1);double base=p.entityInteractionRange();a.addTransientModifier(new AttributeModifier(id,.5,AttributeModifier.Operation.ADD_MULTIPLIED_BASE));eq("Growth modifier increases reach",p.entityInteractionRange(),base*1.5);a.removeModifier(id);eq("Removing growth leaves no stale reach",p.entityInteractionRange(),base);a.setBaseValue(original);p.refreshDimensions();p.setPos(0,80,0);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,ItemStack.EMPTY);
 }
 void vanish(){
  var t=mob(0,80,3);t.getAttribute(Attributes.SCALE).setBaseValue(2);t.refreshDimensions();p.setYRot(0);p.setXRot(0);var spell=h("wizards:arcane_explosion");var old=SpellTarget.SearchResult.of(List.of(t));yes("Server cached target initially eligible",SpatialRules.targetAllowed(p,t));t.addEffect(new MobEffectInstance(fx("rogues:stealth"),140));
  yes("Vanish cannot acquire",!SpellTarget.findTargets(p,spell,old,true).entities().contains(t));yes("Vanish exclusion even without relation filter",!SpellTarget.findTargets(p,spell,old,false).entities().contains(t));
  var cd=((SpellCaster.Player)p).getCooldownManager();cd.reset(null);float before=t.getHealth();SpellExecution.performSpell(w,p,spell,SpellTarget.SearchResult.of(List.of(t)),SpellCast.Action.RELEASE,1);eq("Stale native targeted release rejected",t.getHealth(),before);
  var area=h("wizards:frost_nova");lines.add("Area fixture entities="+w.getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(20))+" casterbox="+p.getBoundingBox()+" area="+area.value().target.type+" allowed="+SpatialRules.selectionAllowed(area.value(),p,t));yes("Native untargeted area still acquires vanished hostile",SpellTarget.findTargets(p,area,SpellTarget.SearchResult.empty(),false).entities().contains(t));
  t.invulnerableTime=0;SpellImpactsPerform(spell,t);yes("Untargeted impacts still damage Vanish",t.getHealth()<before);
  t.addEffect(new MobEffectInstance(fx("rogues:stealth"),140));var arrow=projectile("wizards:arcane_missile");arrow.setFollowedTarget(t);yes("Homing cannot lock Vanish",arrow.getFollowedTarget()==null);t.removeEffect(fx("rogues:stealth"));arrow.setFollowedTarget(t);yes("Homing resumes after Vanish expiry",arrow.getFollowedTarget()==t);t.addEffect(new MobEffectInstance(fx("rogues:stealth"),140));SpatialRules.beforeTick(arrow);yes("Existing homing lock cleared",arrow.getFollowedTarget()==null);arrow.discard();
  p.addEffect(new MobEffectInstance(fx("rogues:stealth"),140));yes("Friendly self targeting preserved",SpatialRules.targetAllowed(p,p));p.removeEffect(fx("rogues:stealth"));t.discard();cd.reset(null);
 }
 void SpellImpactsPerform(Holder<Spell> s,LivingEntity t){net.spell_engine.internals.impact.SpellImpacts.performImpacts(w,p,t,p,s,s.value().impacts,context(s),false,Spell.Impact.Action.Type.DAMAGE);}
 void slash(){
  var t=mob(2,80,5);var a=projectile("wizards:fire_slash");Vec3 old=a.getDeltaMovement();a.tick();yes("Free aim Slash acquires nearby enemy",a.getFollowedTarget()==t);double turn=Math.toDegrees(Math.acos(Math.clamp(old.normalize().dot(a.getDeltaMovement().normalize()),-1,1)));yes("Slash turn bounded at two degrees",turn>0&&turn<=2.02);yes("Slash retains positive forward speed",a.getDeltaMovement().length()>.85);t.addEffect(new MobEffectInstance(fx("rogues:stealth"),140));a.tickCount=4;SpatialRules.beforeTick(a);yes("Slash drops vanished enemy",a.getFollowedTarget()==null);t.discard();a.discard();
  var far=mob(12,80,12);a=projectile("wizards:fire_slash");a.tick();yes("Slash detection stays within8",a.getFollowedTarget()==null);a.discard();far.discard();
 }
 void boundary(){
  p.removeAllEffects();equip();p.setHealth(p.getMaxHealth());PaladinUltimates.startChannel(p,w.getGameTime());var c=PaladinUltimates.channelOf(p);var bs=w.getEntitiesOfClass(BarrierEntity.class,p.getBoundingBox().inflate(20));eq("Native channel creates one boundary",bs.size(),1);var b=bs.getFirst();eq("Base boundary radius",PurgatoryBoundary.radius(b),12);yes("Boundary excludes Priest protection",!PriestUltimates.contains(b,p));
  eq("Purgatory does not intercept projectiles",PriestUltimates.entryTime(b,new Vec3(14,81,0),new Vec3(10,81,0)),-1);
  for(double y:new double[]{77,86})for(double x:new double[]{11.8,12.2}){var delta=new Vec3(x<12?1:-1,0,0);yes("No collision in boundary band above/below wall",PurgatoryBoundary.clipCircle(new Vec3(x,y,0),delta,p.position(),12,5,.3,2).equals(delta));}
  var t=mob(11.5,80,0);t.move(MoverType.SELF,new Vec3(3,0,0));yes("Actual move cannot exit boundary",t.getX()<=11.71);t.setPos(13,80,0);t.move(MoverType.SELF,new Vec3(-5,0,0));yes("Actual move cannot enter boundary",t.getX()>=12.29);t.setPos(0,86,0);t.move(MoverType.SELF,new Vec3(16,0,0));eq("Boundary has no roof above5 blocks",t.getX(),16);t.setPos(9,80,0);PaladinUltimates.pulse(p,c,1);yes("First pulse strong bounded pull",t.getDeltaMovement().x< -1.5&&t.getDeltaMovement().length()<1.7);
  for(double width:new double[]{.3,.6,2,4})for(int sign:new int[]{-1,1}){var v=PurgatoryBoundary.clipCircle(new Vec3(sign*10,80,0),new Vec3(sign*8,0,0),p.position(),12,5,width/2,2);yes("Swept width="+width+" side="+sign,Math.abs(10+sign*v.x)<=12-width/2+.01);}
  yes("Caster may cross own wall",PurgatoryBoundary.clip(p,new Vec3(20,0,0)).equals(new Vec3(20,0,0)));PaladinUltimates.end(p,PaladinUltimates.End.RELEASE);yes("Release discards visual immediately",b.isRemoved());t.setPos(11.5,80,0);t.move(MoverType.SELF,new Vec3(3,0,0));eq("Release clears collision immediately",t.getX(),14.5);t.discard();
  for(var end:PaladinUltimates.End.values()){PaladinUltimates.startChannel(p,w.getGameTime());var owned=w.getEntitiesOfClass(BarrierEntity.class,p.getBoundingBox().inflate(20));PaladinUltimates.end(p,end);yes("Cleanup visual end="+end,owned.stream().allMatch(Entity::isRemoved));}
  equip("skill_tree_rpgs:paladin_tier_4_spell_2_root");PaladinUltimates.startChannel(p,w.getGameTime());var improved=w.getEntitiesOfClass(BarrierEntity.class,p.getBoundingBox().inflate(20)).getFirst();eq("Improved boundary radius14",PurgatoryBoundary.radius(improved),14);PaladinUltimates.end(p,PaladinUltimates.End.CLEANUP);equip();
 }
 void barrage(){
  // ArrowAssist runs on AbstractArrow, independent of the spell creating it.
  var category=net.puffish.skillsmod.api.SkillsAPI.getCategory(Identifier.parse("skill_tree_rpgs:class_skills")).orElseThrow();category.unlock(p);category.resetSkills(p);category.setExtraPoints(p,1000);category.getSkill("418rsvnd17egwkse").orElseThrow().unlock(p);yes("Actual Archer path enables assist",ArrowAssist.archer(p));
  p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.BOW));p.getInventory().setItem(1,new ItemStack(Items.ARROW,64));p.setYRot(0);p.setXRot(0);var target=mob(.2,80,12);target.getAttribute(Attributes.SCALE).setBaseValue(2);target.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);equip("skill_tree_rpgs:archer_tier_3_spell_1_modifier_1");
  net.spell_engine.internals.delivery.arrow.ArrowHelper.shootArrow(w,p,h("archers:barrage"),context(h("archers:barrage")));
  ((net.spell_engine.utils.WorldScheduler)w).schedule(16,()->{try{var arrows=seen;eq("Extensive Barrage launches four arrows",arrows.size(),4);for(var a:arrows){yes("Every volley arrow visited shared assist",a.getPersistentData().contains("class_pack_arrow_assist"));yes("Volley arrow owner remains caster",a.getOwner()==p);// Reuse an identical stationary near-miss fixture for each launched arrow; earlier impacts can move targets.
   category.getSkill("418rsvnd17egwkse").orElseThrow().unlock(p);yes("Archer path active during controlled assist",ArrowAssist.archer(p));a.setPos(0,81.62,0);a.setDeltaMovement(.02,0,1);a.getPersistentData().remove("class_pack_arrow_assist");target.setPos(.2,80,12);target.setHealth(1000);target.setDeltaMovement(Vec3.ZERO);ArrowAssist.tick(new net.neoforged.neoforge.event.tick.EntityTickEvent.Pre(a));lines.add("ASSIST "+a.getPersistentData()+" target="+target.position()+" alive="+target.isAlive()+" near="+target.getBoundingBox());yes("Volley arrow acquires through ordinary assist handler",a.getPersistentData().getStringOr("assist_target", "").equals(target.getUUID().toString()));}target.discard();finish(null);}catch(Throwable e){finish(e);}});
 }
}

